import react from '@vitejs/plugin-react'
import { tanstackRouter } from '@tanstack/router-plugin/vite'
import { defineConfig } from 'vite'

const backend = process.env.BACKEND_ORIGIN ?? 'http://localhost:8080'

/**
 * The Spring application runs as its own process; these are the two prefixes it
 * owns. Proxying them keeps the browser on one origin in development, so CORS
 * and cookies behave the way they will behind a single origin in production.
 */
const backendPrefixes = ['/api', '/internal', '/v3/api-docs']

export default defineConfig({
  plugins: [
    tanstackRouter({ target: 'react', autoCodeSplitting: true }),
    react(),
  ],
  server: {
    port: 5173,
    strictPort: true,
    proxy: Object.fromEntries(
      backendPrefixes.map((prefix) => [
        prefix,
        {
          target: backend,
          changeOrigin: true,
          // The event stream must reach the browser as it is written. Node's
          // HTTP client offers gzip by default, and a compressed response is
          // held in the encoder until it has enough bytes to emit — which for
          // an event every few seconds means the whole stream arrives in a
          // clump when the connection closes, and only in development.
          headers: { 'Accept-Encoding': 'identity' },
        },
      ]),
    ),
  },
})

