import http from 'node:http'
import zlib from 'node:zlib'

const port = Number(process.argv[2])
const compress = process.argv[3] === 'gzip'

http
  .createServer((req, res) => {
    const accepts = req.headers['accept-encoding'] ?? ''
    const gzip = compress && String(accepts).includes('gzip')

    const headers = {
      'Content-Type': 'text/event-stream',
      'Cache-Control': 'no-cache',
      Connection: 'keep-alive',
    }
    if (gzip) headers['Content-Encoding'] = 'gzip'
    res.writeHead(200, headers)

    const sink = gzip ? zlib.createGzip() : null
    if (sink) sink.pipe(res)
    const write = (chunk) => (sink ? sink.write(chunk) : res.write(chunk))

    let n = 0
    const timer = setInterval(() => {
      n += 1
      write(`event: transfer\ndata: {"n":${n}}\n\n`)
      if (n === 5) {
        clearInterval(timer)
        if (sink) sink.end()
        else res.end()
      }
    }, 300)

    req.on('close', () => clearInterval(timer))
  })
  .listen(port, () => console.log(`sse server on ${port} (gzip=${compress})`))

